// src/App.js
import React from 'react';
import 'bootstrap/dist/css/bootstrap.min.css';
import './styles.css';
import HeroCanvas from './components/HeroCanvas';
import { profileData, skillsData, projectsData } from './portfolioData';

function App() {
  return (
    <div>
      <HeroCanvas />
      <div className="container mt-5">
        <header className="mb-5">
          <h1 className="display-4 fw-bold">{profileData.name}</h1>
          <h2 className="h4 text-secondary mb-4">{profileData.title}</h2>
          <div className="d-flex gap-3">
            <a href={`mailto:${profileData.email}`} className="text-decoration-none accent-text fw-bold">Email</a>
            <a href={profileData.github} className="text-decoration-none accent-text fw-bold" target="_blank" rel="noreferrer">GitHub</a>
            <a href={profileData.linkedin} className="text-decoration-none accent-text fw-bold" target="_blank" rel="noreferrer">LinkedIn</a>
          </div>
        </header>

        <section className="mb-5">
          <h3 className="mb-3 border-bottom pb-2">Technical Expertise</h3>
          <div className="mb-3">
            <strong>AI & Data Science: </strong>
            {skillsData.ai.map(skill => <span key={skill} className="tech-badge">{skill}</span>)}
          </div>
          <div>
            <strong>Software & Web: </strong>
            {skillsData.dev.map(skill => <span key={skill} className="tech-badge">{skill}</span>)}
          </div>
        </section>

        <section>
          <h3 className="mb-4 border-bottom pb-2">Project Showcase</h3>
          <div className="row">
            {projectsData.map((project, index) => (
              <div className="col-md-6" key={index}>
                <div className="project-card">
                  <h4 className="h5 fw-bold">{project.title}</h4>
                  <p className="text-muted small mb-3">{project.description}</p>
                  <div>
                    {project.tech.map(t => <span key={t} className="tech-badge">{t}</span>)}
                  </div>
                </div>
              </div>
            ))}
          </div>
        </section>
      </div>
    </div>
  );
}

export default App;
